let preferredPayment='';
try{const stored=localStorage.getItem('valeria-payment-preference');if(SHOP_CONFIG.paymentMethods.includes(stored))preferredPayment=stored;}catch{}
const validEmail=s=>typeof s==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
const contactEmail=validEmail(SHOP_CONFIG.contactEmail)?SHOP_CONFIG.contactEmail:'';
const whatsappNumber=String(SHOP_CONFIG.whatsapp||'').replace(/[^0-9]/g,'');
function draftLink(){return 'mailto:'+encodeURIComponent(contactEmail)+'?subject='+encodeURIComponent('Valeria Sports Wears — Product enquiry')+'&body='+encodeURIComponent(cart.length?enquiryText():'Hello Valeria,\n\nI would like to ask about a product, size or delivery.\n\nPreferred payment: '+(preferredPayment||'Not selected'));}
function renderContact(){const e=document.querySelector('#contact-channels');e.innerHTML=(contactEmail?`<a class="contact-channel" href="mailto:${esc(contactEmail)}"><span>EMAIL US</span><strong>${esc(contactEmail)}</strong><b>↗</b></a>`:'<p class="contact-pending">The shop’s contact email is being set up. Save an enquiry from your bag in the meantime.</p>')+(whatsappNumber.length>=8&&whatsappNumber.length<=15?`<a class="contact-channel" href="https://wa.me/${whatsappNumber}" target="_blank" rel="noopener noreferrer"><span>WHATSAPP</span><strong>Chat with Valeria</strong><b>↗</b></a>`:'');}
function renderPayments(){document.querySelector('#payment-options').innerHTML=SHOP_CONFIG.paymentMethods.map((m,i)=>`<label class="payment-option"><input type="radio" name="payment-method" value="${esc(m)}" ${preferredPayment===m?'checked':''}><span class="payment-symbol">${['CARD','P','支','微','₿','◈','GIFT'][i]||'↗'}</span><span>${esc(m)}</span></label>`).join('');document.querySelectorAll('[name="payment-method"]').forEach(el=>el.onchange=()=>{preferredPayment=el.value;try{localStorage.setItem('valeria-payment-preference',preferredPayment)}catch{}toast('Payment preference saved for your enquiry');});let checkout;try{const u=new URL(SHOP_CONFIG.checkoutUrl);if(u.protocol==='https:')checkout=u.href;}catch{}document.querySelector('#payment-status').textContent=checkout?'Confirm your items and seller quote before using the merchant checkout.':'Cards, PayPal, Alipay, WeChat Pay, crypto and gift cards are offered as payment preferences. Online checkout and wallet payments are not connected yet. For crypto, confirm the coin, network and amount directly with Valeria before any transfer. Gift card issuer and redemption terms must be agreed with Valeria; this site does not redeem codes.';document.querySelector('#payment-checkout').innerHTML=checkout?`<a class="btn dark" href="${esc(checkout)}" target="_blank" rel="noopener noreferrer">Open merchant checkout ↗</a>`:'';}
document.querySelector('#contact-enquiry').onclick=()=>{renderCart();document.querySelector('#cart-modal').showModal();};
const baseEnquiryText=enquiryText;
enquiryText=function(){return baseEnquiryText()+'\nPreferred payment: '+(preferredPayment||'Not selected')+'\nPayment method is a preference only; payment has not been taken.';};
const baseRenderCart=renderCart;
renderCart=function(){baseRenderCart();const actions=document.querySelector('#cart-modal .cart-actions');if(actions&&cart.length){const link=document.createElement('a');link.className='btn light';link.textContent=contactEmail?'Email enquiry ↗':'Contact & payment options ↗';link.href=contactEmail?draftLink():'#contact';if(!contactEmail)link.onclick=()=>document.querySelector('#cart-modal').close();else link.onclick=()=>{link.href=draftLink();};actions.append(link);const note=document.createElement('p');note.className='draft-note';note.textContent=contactEmail?'Email enquiry opens your email app with a draft. Review and send it yourself.':'Choose a payment preference in the Contact section; it will appear in your downloaded enquiry.';actions.after(note);}};
const baseRenderContact=renderContact;
renderContact=function(){baseRenderContact();if(SHOP_CONFIG.wechat){const block=document.createElement('div');block.className='wechat-contact';block.innerHTML=`<span>WECHAT CONTACT</span><div><strong>${esc(SHOP_CONFIG.wechat)}</strong><button id="copy-wechat" aria-label="Copy WeChat contact number">Copy ↗</button></div><small>Add this number in WeChat to contact Valeria.</small>`;document.querySelector('#contact-channels').append(block);block.querySelector('button').onclick=async()=>{try{await navigator.clipboard.writeText(SHOP_CONFIG.wechat);toast('WeChat contact number copied');}catch{toast('WeChat contact: '+SHOP_CONFIG.wechat)}};}};
renderContact();renderPayments();
